baseid = 551030000
dungeonid = 551030001
dungeons = 19

function enter(pi)
    local i
    if (pi.getMapId() == baseid) then
        if (pi.getPlayer().getFame() < 10) then
            pi.playerMessage(5, "您必須擁有10名聲才能進入.")
            do return end
        end
        if (pi.getParty() ~= nil) then
            if pi.isLeader() then
                i = 0
                while (i < dungeons) do
                    if (pi.getPlayerCount(__add(dungeonid, i)) == 0) then
                        pi.warpParty(__add(dungeonid, i))
                        do return end
                    end
                    i = i + 1
                end
            else
                pi.playerMessage(5, "你不是隊長.")
            end
        else
            i = 0
            while (i < dungeons) do
                if (pi.getPlayerCount(__add(dungeonid, i)) == 0) then
                    pi.warp(__add(dungeonid, i))
                    do return end
                end
                i = i + 1
            end
        end
        pi.playerMessage(5, "All of the Mini-Dungeons are in use right now, please try again later.")
    else
        pi.playPortalSE()
        pi.warp(baseid, "MD00")
    end
end
